function readLanguage(): Language {
  try { return window.localStorage.getItem(languageStorageKey) === 'th' ? 'th' : 'en'; }
  catch { return 'en'; }
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(readLanguage);
  useEffect(() => { document.documentElement.lang = language; }, [language]);
  const setLanguage = useCallback((next: Language) => {
    setLanguageState(next);
    try { window.localStorage.setItem(languageStorageKey, next); } catch { /* Language selection still works in memory. */ }
  }, []);
  const t = useCallback((text: string) => language === 'th' ? thai[text] ?? text : text, [language]);
  const value = useMemo(() => ({ language, setLanguage, t }), [language, setLanguage, t]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useI18n must be used inside I18nProvider.');
  return value;
}
